-- Backfill the registry from the tables that already hold persons: a
-- topic subscription, a category preference, or a push enrollment is
-- each an act that makes a person known. The earliest evidence sets
-- first_seen; a person only named in a send stays unregistered.
INSERT OR IGNORE INTO "audience_members" ("id", "person", "first_seen", "updated_at")
SELECT randomblob(16), "person", min("created_at"), min("created_at")
FROM (
	SELECT "person", "created_at" FROM "topic_subscriptions"
	UNION ALL
	SELECT "person", "created_at" FROM "category_preferences"
	UNION ALL
	SELECT "person", "created_at" FROM "push_endpoints"
) "known"
GROUP BY "person";
